          "model": "An extensive system generally uses larger land areas and lower animal density, with cattle obtaining much of their feed by grazing pasture or rangeland. This can increase exposure to seasonal changes in pasture and water. An intensive finishing system concentrates cattle in a smaller managed facility and supplies a formulated diet. Feed, water and infrastructure are managed more directly, although outcomes still depend on environment, management and current requirements.",
